head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.link_num = '';
scwin.acpt_num = '';
scwin.gDepCd = js_dep_cd;
// 사이버정보분석팀일경우 팀코드가 시장마다 다르기 때문에 상위부서코드로 넣어준다. 20240510
if (scwin.gDepCd.substring(0, 2) === '5B') {
    scwin.gDepCd = '5B10';
}
scwin.gEmpNo = js_emp_no;
scwin.key_row = frame.opener.scwin.key_row;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.read();
        setTimeout("fn_init()", 1000); // 데이터 로딩시간이 있어 1초후 화면초기화 작업한다.
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10802.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // (유가/코스닥)공시총괄팀 당번아이디로 수정할수 있게 세팅.
    if (js_dep_cd === '2600' || js_dep_cd === '3400') {
        scwin.gDepCd = txb_DEP_CD2.getValue();
    }
    txb_NOTI_SEQ.hide();
    txb_ISUR_CD.hide();
    txb_EMP_NO.hide();
    for (let i = 1; i < 4; i++) {
        $p.getComponentById("txb_ACPT_NO" + i).hide();
        $p.getComponentById("txb_DEP_CD" + i).hide();
        const dep_cd = $p.getComponentById("txb_DEP_CD" + i).getValue();
        // alert("gDepCd : " + gDepCd + " : dep_cd : " + dep_cd);
        if (scwin.gDepCd === dep_cd) {
            $p.getComponentById("txb_REMK" + i).setReadOnly("");
        } else {
            $p.getComponentById("txb_REMK" + i).style.backgroundColor = '#b9d4f7';
        }

        // 시장감시부일때만 '공시시각','반송사유' 를 보여주고 다른팀일때 보여주지 않는다.
        if (scwin.gDepCd !== '5B10') {
            if (i === 1) {
                label_13.hide();
                label_18.hide();
                label_25.hide();
                panel_1.style.height = 457;
                panel_2.style.height = 145;
                btn_Save.style.top = 357;
                btn_Cancel.style.top = 357;
                label_31.style.top = 357;
                label_21.style.top = 378;
                label_22.style.top = 399;
                label_23.style.top = 420;
                label_24.style.top = 441;
            }
            $p.getComponentById("txb_DISCLS_DDTM" + i).hide();
            $p.getComponentById("txb_RET_RSN" + i).hide();
        }
    }
    $c.cm.PanelToGroupBox(panel_1);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Sub_OnFail
 * @description Sub On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Sub_OnFail = async function() {
    try {
        await $c.win.alert(trs_Sub);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10802.trs_Sub_OnFail" });
    }
};

/**
 * @method
 * @name trs_Sub_OnSuccess
 * @description Sub On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Sub_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
        await $c.win.alert(msg);
        const fr_fn_Search = $c.frame.path("../").fn_Search;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10802.trs_Sub_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Save_onclick = function() {
    try {
        scwin.save();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10802.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10802.btn_Cancel_onclick" });
    }
};

/**
 * @method
 * @name txb_ACPT_STAT1_ondblclick
 * @description txb_ACPT_STAT1 더블클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_ACPT_STAT1_ondblclick = async function() {
    try {
        await scwin.onlineAcpt('1');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10802.txb_ACPT_STAT1_ondblclick" });
    }
};

/**
 * @method
 * @name txb_ACPT_STAT2_ondblclick
 * @description txb_ACPT_STAT2 더블클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_ACPT_STAT2_ondblclick = async function() {
    try {
        await scwin.onlineAcpt('2');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10802.txb_ACPT_STAT2_ondblclick" });
    }
};

/**
 * @method
 * @name txb_ACPT_STAT3_ondblclick
 * @description txb_ACPT_STAT3 더블클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_ACPT_STAT3_ondblclick = async function() {
    try {
        await scwin.onlineAcpt('3');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10802.txb_ACPT_STAT3_ondblclick" });
    }
};

/**
 * @method
 * @name txb_ACPT_STAT4_ondblclick
 * @description txb_ACPT_STAT4 더블클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_ACPT_STAT4_ondblclick = async function() {
    try {
        await scwin.onlineAcpt('4');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10802.txb_ACPT_STAT4_ondblclick" });
    }
};

/**
 * @method
 * @name txb_DISCLS_DDTM2_ondblclick
 * @description txb_DISCLS_DDTM2 더블클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_DISCLS_DDTM2_ondblclick = async function() {
    try {
        await scwin.openDiscls('2');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10802.txb_DISCLS_DDTM2_ondblclick" });
    }
};

/**
 * @method
 * @name txb_DISCLS_DDTM3_ondblclick
 * @description txb_DISCLS_DDTM3 더블클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_DISCLS_DDTM3_ondblclick = async function() {
    try {
        await scwin.openDiscls('3');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10802.txb_DISCLS_DDTM3_ondblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    url += "&NOTI_SEQ=" + frame.opener.dts_Grid.getCellData(scwin.key_row, "NOTI_SEQ");
    url += "&ISUR_CD=" + frame.opener.dts_Grid.getCellData(scwin.key_row, "ISUR_CD");
    url += "&SCREN_ID=" + 'ULDSTF10802.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Master",
        action : "/OnlineNotice.do",
        ref : "",
        target : "dts_Master=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&NOTI_SEQ=" + frame.opener.dts_Grid.getCellData(scwin.key_row, "NOTI_SEQ");
    url += "&ISUR_CD=" + frame.opener.dts_Grid.getCellData(scwin.key_row, "ISUR_CD");
    url += "&SCREN_ID=" + 'ULDSTF10802.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions2 = {
        id : "sbm_dts_Sub",
        action : "/OnlineNotice.do",
        ref : "",
        target : "dts_Sub=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {void}
 * @hidden N
 */
scwin.save = function() {
    txb_EMP_NO.setValue(scwin.gEmpNo);
    const res = window.confirm("[저장]하시겠습니까?");
    if (res) {
        gLastJob = "저장";
        let url = "/OnlineNotice.do?method=saveDetailOnlineNotice" + "&SCREN_ID=" + 'ULDSTF10802.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        // alert(dts_MASTER.Text);
        trs_Sub.Action = url;
        trs_Sub.KeyName = "toinb_dataid4";
        trs_Sub.KeyValue = "JSP(I:pInputMaster=dts_Sub)";
        trs_Sub.post();
    }
};

/**
 * @method
 * @name openDiscls
 * @description open Discls 처리
 * @param {*} num num
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDiscls = async function(num) {
    fn_SetPar = scwin.setDiscls;
    scwin.link_num = num;
    if (scwin.gDepCd !== '5B10' || $p.getComponentById("txb_DEP_CD" + num).getValue() === '') {
        // alert("시장감시부에서만 공시연결할 수 있습니다.");
        return;
    }
    if ($p.getComponentById("txb_ACPT_STAT" + scwin.link_num).getValue() === '접수' || $p.getComponentById("txb_ACPT_STAT" + scwin.link_num).getValue() === '반송거부') {
        const options = {
            id: "ULDSTF30007",
            title: "공시선택",
            type: "browserPopup",
            width: "10px",
            height: "20px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclmgt/ULDSTF30007.gfm", options);
    } else {
        await $c.win.alert("[접수],[반송거부]상태에서 공시연결 할 수 있습니다.");
    }
};

/**
 * @method
 * @name setDiscls
 * @description 공시팝업에서 공시선택시 값 셋팅.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setDiscls = function(arrPar) {
    // 공시팝업에서 공시선택시 값 셋팅.
    // alert("arrPar[0] : " + arrPar[0] + " : arrPar[1] : " + arrPar[1] + " :arrPar[2] : " + arrPar[2]);
    const acpt_no = arrPar[0];
    const discls_title = arrPar[1];
    let discls_date = arrPar[2];
    discls_date = discls_date.substring(0, 4) + "-" + discls_date.substring(4, 6) + "-" + discls_date.substring(6, 8) + " " + discls_date.substring(8, 10) + ":" + discls_date.substring(10, 12) + "(" + discls_title + ")";
    $p.getComponentById("txb_ACPT_NO" + scwin.link_num).setValue(acpt_no);
    $p.getComponentById("txb_DISCLS_DDTM" + scwin.link_num).setValue(discls_date);
};

/**
 * @method
 * @name onlineAcpt
 * @description online Acpt 처리
 * @param {*} num num
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onlineAcpt = async function(num) {
    scwin.acpt_num = num;
    const wrtr_dep_cd = $p.getComponentById("txb_DEP_CD" + num).getValue();
    if ($p.getComponentById("txb_ACPT_STAT" + scwin.acpt_num).getValue() === '미접수') {
        /* 기존 상세뷰(30412)에서 호출했으나 장과장님 요청으로  리스트(30410)부분에서 호출변경 여기서 호출은 반송외에는 막는다.
        if(gDepCd == wrtr_dep_cd) {
        	frame.CreateDialogFrame("ONLINE", "/dsclinfo/ULDSTF30413.gfm", "온라인통보 접수", 100, 100, 550, 280, "window");
        } else {
        	alert("담당부서만 접수할 수 있습니다.");
        }
         */
    } else if ($p.getComponentById("txb_ACPT_STAT" + scwin.acpt_num).getValue() === '반송' && scwin.gDepCd === '5B10') {
        // 반송승인페이지 작업.
        const options = {
            id: "ULDSTF10804",
            title: "온라인통보 반송",
            type: "browserPopup",
            width: "505px",
            height: "280px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclproc/ULDSTF10804.gfm", options);
    }
};
